<script setup lang="ts">
import { reactive,ref } from 'vue'; import { onLoad } from '@dcloudio/uni-app'; import { PrincipalType } from '@express-platform/shared-types'; import { useCourierAuth } from '../../stores/auth'; import { errorMessage } from '../../utils';
const auth=useCourierAuth(); const form=reactive({identifier:'',password:''}); const error=ref(''); const expired=ref(false); onLoad((q)=>{expired.value=q?.reason==='expired';if(auth.authenticated)uni.reLaunch({url:'/pages/workbench/index'});});
async function submit():Promise<void>{error.value='';if(!/^\+[1-9]\d{7,14}$/.test(form.identifier)){error.value='请输入国际格式手机号';return;}if(form.password.length<8){error.value='密码至少 8 位';return;}try{await auth.login({subjectType:PrincipalType.COURIER,...form});uni.showToast({title:'登录成功',icon:'success'});setTimeout(()=>uni.reLaunch({url:'/pages/workbench/index'}),450);}catch(cause:unknown){error.value=errorMessage(cause);}}
</script>
<template><view class="login-page"><view class="brand"><view class="brand-mark">骑</view><view><text class="brand-name">木棉骑手</text><text class="brand-sub">COURIER WORKSPACE</text></view><text class="mock-pill">模拟环境</text></view><view class="welcome"><text class="welcome-small">READY TO DELIVER</text><text class="welcome-title">今天，也要稳稳送达。</text><text class="welcome-copy">接单、取件、配送和签收，每一步由后端状态机守护。</text></view><view class="login-card card"><text class="card-title">配送员登录</text><view v-if="expired" class="notice">登录状态已过期，请重新登录。</view><view class="field"><text>手机号</text><input v-model.trim="form.identifier" placeholder="国际格式手机号" autocomplete="username"/></view><view class="field"><text>密码</text><input v-model="form.password" type="password" placeholder="请输入密码" autocomplete="current-password" @confirm="submit"/></view><view v-if="error" class="form-error">{{error}}</view><button class="primary-button" :loading="auth.submitting" :disabled="auth.submitting" @tap="submit">{{auth.submitting?'正在验证身份…':'进入工作台'}}</button><text class="hint">演示密码不会预填或输出到日志。</text></view></view></template>
<style scoped>
.login-page{position:relative;min-height:100vh;padding:46rpx 34rpx;background:linear-gradient(160deg,#292622 0%,#39332e 46%,#eee9e2 46%,#f6f2ed 100%)}.brand{display:grid;grid-template-columns:68rpx 1fr auto;align-items:center;gap:16rpx;color:#fff}.brand-mark{display:grid;place-items:center;width:68rpx;height:68rpx;border-radius:21rpx 21rpx 21rpx 7rpx;background:#ef6a31;font-size:27rpx;font-weight:900}.brand-name,.brand-sub,.welcome-small,.welcome-title,.welcome-copy,.card-title,.hint{display:block}.brand-name{font-size:28rpx;font-weight:900}.brand-sub{margin-top:3rpx;color:#a89f97;font-size:15rpx;letter-spacing:2rpx}.welcome{margin:88rpx 8rpx 105rpx;color:#fff}.welcome-small{color:#ec8c61;font-size:17rpx;letter-spacing:3rpx;font-weight:800}.welcome-title{margin-top:20rpx;font-size:48rpx;font-weight:900}.welcome-copy{margin-top:16rpx;color:#c8bfb7;font-size:22rpx;line-height:1.6}.login-card{padding:34rpx}.card-title{margin-bottom:30rpx;font-size:34rpx;font-weight:900}.field{margin-bottom:23rpx}.field text{display:block;margin-bottom:10rpx;color:#6f675f;font-size:23rpx;font-weight:800}.field input{height:84rpx;padding:0 22rpx;border-radius:18rpx;background:#f3eee9;font-size:26rpx}.notice,.form-error{margin-bottom:20rpx;padding:17rpx;border-radius:15rpx;font-size:22rpx}.notice{color:#865d25;background:#fff5dd}.form-error{color:#a13e32;background:#fff0ed}.hint{margin-top:20rpx;text-align:center;color:#948a81;font-size:20rpx}
